head.script:
// =============================================================================
/**
 * stf 업무 모듈에서 분리한 인쇄/리포트(출력) 공통 함수.
 * Rexpert 리포트 솔루션 연동: 보고서 오픈/미리보기/PDF 변환, 데이터셋→리포트 JSON 변환.
 * AS-IS 는 $c.rpt.* (origin: report.xml) 로 호출되며, 함수명을 camelCase 로 표준화하고
 * 각 JSDoc 에 AS-IS 원본명을 병기한다.
 *
 * 의존: Rexpert 전역 함수(rex_GetgoDictionay, rex_gfRexRptOpen), $c.frame.* 가 주입되어 있어야 한다.
 * 화면 종속 인쇄 함수(yearanulfee_print 의 fn_pre_print_*, listInvstg 의 fn_print 등)는
 * 본 엔진 함수를 소비하는 호출부로, 본 파일에 포함하지 않고 각 화면 모듈에 잔류한다.
 *
 * @author Inswave Systems
 * @class print
 * @namespace $c.print
 */
// =============================================================================

scwin.onpageload = function () {

};

// -----------------------------------------------------------------------------
// 1. 보고서 오픈 / 미리보기 / PDF (origin: report.xml)
// -----------------------------------------------------------------------------

/**
 * @method
 * @name openReportYear
 * @description 연도 보고서 인쇄(파라미터 없이 openReport 호출). 내부용 보고서 인쇄 - 데이터셋 연동.
 * (AS-IS: fn_open_report_year, origin: report.xml)
 * @param {String} dataSetCSV CSV 문자열 데이터
 * @param {String} rex_rptname 레포트명
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.print.openReportYear(csv, "RLDSTF10007");
 */
scwin.openReportYear = function (dataSetCSV, rex_rptname) {
    scwin.openReport(dataSetCSV, rex_rptname, null);
};

/**
 * @method
 * @name openReport
 * @description 내부용 보고서 인쇄. 멀티 데이터셋(CSV)을 Rexpert preview 팝업으로 연다.
 * (AS-IS: fn_open_report, origin: report.xml)
 * @param {String} dataSetCSV CSV 문자열 데이터
 * @param {String} rex_rptname 레포트명
 * @param {Array} userParam 사용자 파라미터 배열 [{uid, unm}] (옵션)
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.print.openReport(csv, "RLDSTF10007", [{uid:"title", unm:"제목"}]);
 */
scwin.openReport = function (dataSetCSV, rex_rptname, userParam) {
    var oRptMainParam = rex_GetgoDictionay();

    // 필수 - 레포트명
    oRptMainParam.put("rex_rptname", rex_rptname);
    // 필수 - 데이터 타입 설정
    oRptMainParam.put("rex_datatype", "CSVSTR");
    oRptMainParam.put("rex_data", dataSetCSV);

    // 옵션 - 파라미터 정의
    if (userParam != null && userParam.length > 0) {
        for (var i = 0; i < userParam.length; i++) {
            oRptMainParam.put(userParam[i].uid, userParam[i].unm);
        }
    }

    // 옵션 - 팝업설정
    var rex_gsPreViewFeaturesCustom = "center=yes,scrollbars=no,status=no,toolbar=no,resizable=1,location=no,menu=no,width=825,height=1000";
    oRptMainParam.put("rex_open_window", rex_gsPreViewFeaturesCustom);

    // preview 팝업 열기
    rex_gfRexRptOpen("popup", oRptMainParam);
};

/**
 * @method
 * @name printPreView
 * @description 외부용 보고서 인쇄. 단건 XML 연동을 Rexpert preview 모달 팝업으로 연다. 서버구분(_svrGubun)에 따라 데이터 URL 호스트를 분기한다.
 * (AS-IS: fn_PrintPreView, origin: report.xml) — 디버그 alert 제거.
 * @param {String} _rexName 레포트명
 * @param {String} _dataType 데이터 타입
 * @param {String} _dataLocation 데이터 URL 경로
 * @param {String} _dataXPath 데이터 XPath
 * @param {String} _svrGubun 서버구분 (dev/local/test/dr/운영)
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.print.printPreView("RLDSTF10001", "XML", "/data.do", "/root", "dev");
 */
scwin.printPreView = function (_rexName, _dataType, _dataLocation, _dataXPath, _svrGubun) {
    var oRptMainParam = rex_GetgoDictionay();
    oRptMainParam.put("rex_rptname", _rexName);
    oRptMainParam.put("rex_datatype", _dataType);
    if ((_svrGubun == "dev") || (_svrGubun == "local")) {
        oRptMainParam.put("rex_data", "https://idev-staff.krx.co.kr" + _dataLocation);   // 개발&로컬
    } else if (_svrGubun == "test") {
        oRptMainParam.put("rex_data", "https://itest-staff.krx.co.kr" + _dataLocation);  // 테스트
    } else if (_svrGubun == "dr") {
        oRptMainParam.put("rex_data", "https://dr-staff.krx.co.kr" + _dataLocation);     // DR
    } else {
        oRptMainParam.put("rex_data", "https://staff.krx.co.kr" + _dataLocation);        // 운영1,2
    }
    oRptMainParam.put("rex_xpath", _dataXPath);

    // 옵션 - 팝업설정
    var rex_gsPreViewFeaturesModalCustom = "center:yes;resizable__no;scroll:no;status:no;dialogWidth:825px;dialogHeight:768px";
    oRptMainParam.put("rex_open_window", rex_gsPreViewFeaturesModalCustom);

    // preview 팝업 열기
    rex_gfRexRptOpen("popupmodal", oRptMainParam);
};

/**
 * @method
 * @name extractParam
 * @description form 엘리먼트로부터 파라미터를 추출하여 쿼리스트링으로 반환한다.
 * (AS-IS: fn_ExtractParam, origin: report.xml)
 * @param {Object} _frm form 엘리먼트
 * @returns {String} name=value& 형태의 쿼리스트링
 * @hidden N
 * @exception
 * @example var qs = $c.print.extractParam(document.frm);
 */
scwin.extractParam = function (_frm) {
    var params = "";
    var frmEle;
    for (var i = 0; i < _frm.elements.length; i++) {
        frmEle = _frm.elements[i];
        switch (frmEle.type) {
            case "text":
            case "hidden":
            case "password":
            case "textarea":
            case "select-one":
                params += frmEle.name + "=" + encodeURIComponent(frmEle.getValue()) + "&";
                break;
            case "radio":
                if (frmEle.checked) params += frmEle.name + "=" + encodeURIComponent(frmEle.getValue()) + "&";
                break;
            case "checkbox":
                if (frmEle.checked) {
                    params += frmEle.name + "=" + encodeURIComponent(frmEle.getValue());
                    params += "&";
                }
                break;
        }
    }
    return params.substr(0, params.length - 1);
};

/**
 * @method
 * @name openReportPdf
 * @description Rexpert preview → PDF 변환. 숨은 form 을 생성해 PDF 변환 서버로 POST 한다.
 * (AS-IS: fn_open_report_pdf, origin: report.xml)
 * @param {String} pdf_rptname 레포트명
 * @param {Array} userParam 사용자 파라미터 배열 [{uid, unm}] (jsonData 는 JSON.stringify 처리)
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.print.openReportPdf("RLDSTF10007_1", [{uid:"jsonData", unm:json}]);
 */
scwin.openReportPdf = function (pdf_rptname, userParam) {
    if (document.getElementById("pdfPreView")) {
        document.body.removeChild(document.getElementById("pdfPreView"));
    }
    var time = (new Date()).getTime();
    $c.frame.path("/").OuterWindow.window.open("", "pdf_preViewPopup_" + time, "left=0,top=0,width=825,height=768,resizable=yes,scrollbars=no,location=no,status=no");
    var form = document.createElement("form");
    form.setAttribute("id", "pdfPreView");
    form.setAttribute("name", "pdfPreView");
    form.setAttribute("method", "POST");
    form.setAttribute("target", "pdf_preViewPopup_" + time);
    form.setAttribute("action", "/filePdfload.do?method=getPdfInfo");

    // 옵션 - 파라미터 정의
    if (userParam != null && userParam.length > 0) {
        for (var i = 0; i < userParam.length; i++) {
            var hiddenField = document.createElement("input");
            hiddenField.setAttribute("type", "hidden");
            hiddenField.setAttribute("id", userParam[i].uid);
            hiddenField.setAttribute("name", userParam[i].uid);
            if (userParam[i].uid.indexOf("jsonData") != -1) {
                hiddenField.setAttribute("value", JSON.stringify(userParam[i].unm));
            } else {
                hiddenField.setAttribute("value", userParam[i].unm);
            }
            form.appendChild(hiddenField);
        }
        var rptField = document.createElement("input");
        rptField.setAttribute("type", "hidden");
        rptField.setAttribute("id", "pdf_rptname");
        rptField.setAttribute("name", "pdf_rptname");
        rptField.setAttribute("value", pdf_rptname);
        form.appendChild(rptField);
    }
    document.body.appendChild(form);
    form.submit();
};

// -----------------------------------------------------------------------------
// 2. 데이터셋 → 리포트 데이터(Array/JSON) 변환 (origin: report.xml)
// -----------------------------------------------------------------------------

/**
 * @method
 * @name makeDtsToArrOut
 * @description 데이터가 없을 때, 헤더만으로 빈 껍데기(uid="&nbsp;") userParam 배열을 구성한다.
 * (AS-IS: fn_make_dtsToArrOut, origin: report.xml)
 * @param {Array} userParam 누적 배열
 * @param {Object} dtsObj 데이터셋
 * @returns {Array} userParam
 * @hidden N
 * @exception
 * @example $c.print.makeDtsToArrOut([], dts);
 */
scwin.makeDtsToArrOut = function (userParam, dtsObj) {
    var dtsObjHeaders = (dtsObj.DataHeader).split(",");
    var dtsHeaders;
    var dtsHeaderNm;
    var tmpObj;
    for (var k = 0; k < dtsObjHeaders.length; k++) {
        tmpObj = new Object();
        dtsHeaders = (dtsObjHeaders[k]).split(":");
        dtsHeaderNm = dtsHeaders[0];
        tmpObj.uid = dtsHeaderNm;
        tmpObj.unm = "&nbsp;";
        userParam.push(tmpObj);
    }
    return userParam;
};

/**
 * @method
 * @name makeDtsToArr1Wdf
 * @description 데이터셋을 포맷(dataFormatObj) 적용하여 Array(userParam) 형태로 변환한다(단일 데이터셋).
 * (AS-IS: fn_make_dtsToArr1_wdf, origin: report.xml)
 * @param {Array} userParam 누적 배열
 * @param {Object} dtsObj 데이터셋
 * @param {Array} dataFormatObj 포맷 정의 ["헤더명:포맷타입", ...]
 * @returns {Array} userParam
 * @hidden N
 * @exception
 * @example $c.print.makeDtsToArr1Wdf([], dts, ["AMT:FormatNumberEx"]);
 */
scwin.makeDtsToArr1Wdf = function (userParam, dtsObj, dataFormatObj) {
    if (dtsObj == null || dtsObj.getTotalRow() == 0) {
        return scwin.makeDtsToArrOut(userParam, dtsObj);
    }
    var dtsObjHeaders = (dtsObj.DataHeader).split(",");
    var dtsHeaders, dtsHeaderNm, dtsHeaderType, tmpObj, dtsReportValue, dfObj, dfHeaderNm, dfNm;
    for (var j = 1; j <= dtsObj.getTotalRow(); j++) {
        for (var k = 0; k < dtsObjHeaders.length; k++) {
            tmpObj = new Object();
            dtsHeaders = (dtsObjHeaders[k]).split(":");
            dtsHeaderNm = dtsHeaders[0];
            dtsHeaderType = dtsHeaders[1];
            dtsReportValue = scwin.getDtsValue(dtsObj, j, dtsHeaderType, dtsHeaderNm);
            if (dataFormatObj != null && dataFormatObj.length > 0) {
                for (var m = 0; m < dataFormatObj.length; m++) {
                    dfObj = (dataFormatObj[m]).split(":");
                    dfHeaderNm = dfObj[0];
                    dfNm = dfObj[1];
                    if (dtsHeaderNm == dfHeaderNm) {
                        dtsReportValue = scwin.dataFormatValue(dfNm, dtsReportValue);
                        break;
                    }
                }
            }
            tmpObj.uid = dtsHeaderNm;
            tmpObj.unm = dtsReportValue;
            userParam.push(tmpObj);
        }
    }
    return userParam;
};

/**
 * @method
 * @name makeDtsToJsonOut
 * @description 데이터가 없을 때, 헤더만으로 빈 껍데기 JSON 배열을 구성한다.
 * (AS-IS: fn_make_dtsToJsonOut, origin: report.xml)
 * @param {Object} dtsObj 데이터셋
 * @returns {Array} 빈 껍데기 객체 1건이 담긴 배열
 * @hidden N
 * @exception
 * @example $c.print.makeDtsToJsonOut(dts);
 */
scwin.makeDtsToJsonOut = function (dtsObj) {
    var rtnArray = new Array();
    var tmpObj = new Object();
    var dtsObjHeaders = (dtsObj.DataHeader).split(",");
    var dtsHeaders;
    var dtsHeaderNm;
    for (var k = 0; k < dtsObjHeaders.length; k++) {
        dtsHeaders = (dtsObjHeaders[k]).split(":");
        dtsHeaderNm = dtsHeaders[0];
        tmpObj[dtsHeaderNm] = "&nbsp;";
    }
    rtnArray.push(tmpObj);
    return rtnArray;
};

/**
 * @method
 * @name makeDtsToJson1
 * @description 데이터셋을 JSON({arrayData:[...]}) 형태로 변환한다.
 * (AS-IS: fn_make_dtsToJson1, origin: report.xml)
 * @param {Object} dtsReportObj 데이터셋
 * @returns {Object} { arrayData: Array }
 * @hidden N
 * @exception
 * @example $c.print.makeDtsToJson1(dts);
 */
scwin.makeDtsToJson1 = function (dtsReportObj) {
    var rtnArray = new Array();
    if (dtsReportObj == null || dtsReportObj.getTotalRow() == 0) {
        rtnArray = scwin.makeDtsToJsonOut(dtsReportObj);
        return { arrayData: rtnArray };
    }
    var dtsObjHeaders = (dtsReportObj.DataHeader).split(",");
    var dtsHeaders, dtsHeaderNm, dtsHeaderType, tmpObj;
    for (var j = 1; j <= dtsReportObj.getTotalRow(); j++) {
        tmpObj = new Object();
        for (var k = 0; k < dtsObjHeaders.length; k++) {
            dtsHeaders = (dtsObjHeaders[k]).split(":");
            dtsHeaderNm = dtsHeaders[0];
            dtsHeaderType = dtsHeaders[1];
            tmpObj[dtsHeaderNm] = scwin.getDtsValue(dtsReportObj, j, dtsHeaderType, dtsHeaderNm);
        }
        rtnArray.push(tmpObj);
    }
    return { arrayData: rtnArray };
};

/**
 * @method
 * @name makeDtsToJson1Wdf
 * @description 데이터셋을 포맷(dataFormatObj) 적용하여 JSON 형태로 변환한다.
 * (AS-IS: fn_make_dtsToJson1_wdf, origin: report.xml)
 * @param {Object} dtsReportObj 데이터셋
 * @param {Array} dataFormatObj 포맷 정의 ["헤더명:포맷타입", ...]
 * @returns {Object} { arrayData: Array }
 * @hidden N
 * @exception
 * @example $c.print.makeDtsToJson1Wdf(dts, ["AMT:FormatNumberEx"]);
 */
scwin.makeDtsToJson1Wdf = function (dtsReportObj, dataFormatObj) {
    var rtnArray = new Array();
    if (dtsReportObj == null || dtsReportObj.getTotalRow() == 0) {
        rtnArray = scwin.makeDtsToJsonOut(dtsReportObj);
        return { arrayData: rtnArray };
    }
    var dtsObjHeaders = (dtsReportObj.DataHeader).split(",");
    var dtsHeaders, dtsHeaderNm, dtsHeaderType, dfObj, dfHeaderNm, dfNm, tmpObj, dtsReportValue;
    for (var j = 1; j <= dtsReportObj.getTotalRow(); j++) {
        tmpObj = new Object();
        for (var k = 0; k < dtsObjHeaders.length; k++) {
            dtsHeaders = (dtsObjHeaders[k]).split(":");
            dtsHeaderNm = dtsHeaders[0];
            dtsHeaderType = dtsHeaders[1];
            dtsReportValue = scwin.getDtsValue(dtsReportObj, j, dtsHeaderType, dtsHeaderNm);
            if (dataFormatObj != null && dataFormatObj.length > 0) {
                for (var m = 0; m < dataFormatObj.length; m++) {
                    dfObj = (dataFormatObj[m]).split(":");
                    dfHeaderNm = dfObj[0];
                    dfNm = dfObj[1];
                    if (dtsHeaderNm == dfHeaderNm) {
                        dtsReportValue = scwin.dataFormatValue(dfNm, dtsReportValue);
                        break;
                    }
                }
            }
            tmpObj[dtsHeaderNm] = dtsReportValue;
        }
        rtnArray.push(tmpObj);
    }
    return { arrayData: rtnArray };
};

/**
 * @method
 * @name makeDtsToJson1WdfWsum
 * @description 데이터셋을 포맷 적용하여 JSON 으로 변환하고, 합계(dataSumObj) 대상 컬럼은 합산하여 userParam 에 담는다.
 * (AS-IS: fn_make_dtsToJson1_wdf_wsum, origin: report.xml)
 * 특정 합계 컬럼(ISU_TOTAMT_SUM 등)은 십만 단위 반올림(소수 3자리) 보정한다.
 * @param {Object} dtsReportObj 데이터셋
 * @param {Array} dataFormatObj 포맷 정의 ["헤더명:포맷타입", ...]
 * @param {Array} dataSumObj 합계 정의 ["합계키:헤더명(:포맷)", ...]
 * @param {Array} userParam 합계 결과를 담을 배열
 * @returns {Array} [ {arrayData:[...]}, userParam ]
 * @hidden N
 * @exception
 * @example $c.print.makeDtsToJson1WdfWsum(dts, fmt, sum, []);
 */
scwin.makeDtsToJson1WdfWsum = function (dtsReportObj, dataFormatObj, dataSumObj, userParam) {
    var rtnArray = new Array();
    var rtnJosnArr = new Array();
    if (dtsReportObj == null || dtsReportObj.getTotalRow() == 0) {
        rtnJosnArr = scwin.makeDtsToJsonOut(dtsReportObj);
        rtnArray[0] = { arrayData: rtnJosnArr };
        rtnArray[1] = userParam;
        return rtnArray;
    }
    var dtsObjHeaders = (dtsReportObj.DataHeader).split(",");
    var dtsHeaders, dtsHeaderNm, dtsHeaderType, dfObj, dfHeaderNm, dfNm;
    var dSumObj, dSumToNm, dSumHeaderNm, dSumFormatNm;
    var dSumRtnArr = new Array();
    var tmpObj, dtsReportValue;
    for (var j = 1; j <= dtsReportObj.getTotalRow(); j++) {
        tmpObj = new Object();
        for (var k = 0; k < dtsObjHeaders.length; k++) {
            dtsHeaders = (dtsObjHeaders[k]).split(":");
            dtsHeaderNm = dtsHeaders[0];
            dtsHeaderType = dtsHeaders[1];
            dtsReportValue = scwin.getDtsValue(dtsReportObj, j, dtsHeaderType, dtsHeaderNm);
            if (dataSumObj != null && dataSumObj.length > 0) {
                for (var n = 0; n < dataSumObj.length; n++) {
                    dSumObj = (dataSumObj[n]).split(":");
                    dSumToNm = dSumObj[0];
                    dSumHeaderNm = dSumObj[1];
                    if (dtsHeaderNm == dSumHeaderNm) {
                        if (dSumRtnArr[dSumToNm] == null) {
                            dSumRtnArr[dSumToNm] = dtsReportValue;
                        } else {
                            dSumRtnArr[dSumToNm] = parseFloat(dSumRtnArr[dSumToNm]) + parseFloat(dtsReportValue);
                        }
                        break;
                    }
                }
            }
            if (dataFormatObj != null && dataFormatObj.length > 0) {
                for (var m = 0; m < dataFormatObj.length; m++) {
                    dfObj = (dataFormatObj[m]).split(":");
                    dfHeaderNm = dfObj[0];
                    dfNm = dfObj[1];
                    if (dtsHeaderNm == dfHeaderNm) {
                        dtsReportValue = scwin.dataFormatValue(dfNm, dtsReportValue);
                        break;
                    }
                }
            }
            tmpObj[dtsHeaderNm] = dtsReportValue;
        }
        rtnJosnArr.push(tmpObj);
    }
    var dSumRtnVal;
    // ISU_TOTAMT_SUM 등 합계 컬럼은 전체 합산 후 십만 단위/소수 3자리 반올림 보정
    for (var key in dSumRtnArr) {
        dSumRtnVal = dSumRtnArr[key];
        if (key == "ISU_TOTAMT_SUM" || key == "FST_ISU_TOT_AMT_SUM" || key == "EXIST_ISU_TOT_AMT_SUM" ||
            key == "ADD_ISU_TOTAMT_SUM" || key == "ACC_ISU_TOTAMT_SUM") {
            dSumRtnVal = Math.round(dSumRtnVal / 100000) / 1000;
            dSumRtnArr[key] = dSumRtnVal;
        }
    }
    for (var key2 in dSumRtnArr) {
        dSumRtnVal = dSumRtnArr[key2];
        for (var n2 = 0; n2 < dataSumObj.length; n2++) {
            dSumObj = (dataSumObj[n2]).split(":");
            dSumToNm = dSumObj[0];
            dSumHeaderNm = dSumObj[1];
            if (dSumObj.length == 3) {
                // Format 이 있을 시만
                dSumFormatNm = dSumObj[2];
                if (key2 == dSumToNm) {
                    if (!$c.util.isEmpty(dSumFormatNm) && dSumFormatNm != "") {
                        dSumRtnVal = scwin.dataFormatValue(dSumFormatNm, dSumRtnVal);
                    }
                    break;
                }
            }
        }
        userParam.push({ uid: key2, unm: dSumRtnVal });
    }
    rtnArray[0] = { arrayData: rtnJosnArr };
    rtnArray[1] = userParam;
    return rtnArray;
};

/**
 * @method
 * @name makeDtsToJson2
 * @description dtsObj 헤더 모양으로 dtsReportObj 데이터를 JSON 형태로 변환한다.
 * (AS-IS: fn_make_dtsToJson2, origin: report.xml)
 * @param {Object} dtsObj 헤더 기준 데이터셋
 * @param {Object} dtsReportObj 변환 대상 데이터셋
 * @returns {Object} { arrayData: Array }
 * @hidden N
 * @exception
 * @example $c.print.makeDtsToJson2(dtsHdr, dtsData);
 */
scwin.makeDtsToJson2 = function (dtsObj, dtsReportObj) {
    var rtnArray = new Array();
    if (dtsReportObj == null || dtsReportObj.getTotalRow() == 0) {
        rtnArray = scwin.makeDtsToJsonOut(dtsObj);
        return { arrayData: rtnArray };
    }
    var dtsObjHeaders = (dtsObj.DataHeader).split(",");
    var dtsHeaders, dtsHeaderNm, dtsHeaderType, tmpObj;
    for (var j = 1; j <= dtsReportObj.getTotalRow(); j++) {
        tmpObj = new Object();
        for (var k = 0; k < dtsObjHeaders.length; k++) {
            dtsHeaders = (dtsObjHeaders[k]).split(":");
            dtsHeaderNm = dtsHeaders[0];
            dtsHeaderType = dtsHeaders[1];
            tmpObj[dtsHeaderNm] = scwin.getDtsValue(dtsReportObj, j, dtsHeaderType, dtsHeaderNm);
        }
        rtnArray.push(tmpObj);
    }
    return { arrayData: rtnArray };
};

/**
 * @method
 * @name makeDtsToJson2Wdf
 * @description dtsObj 헤더 모양으로 dtsReportObj 데이터를 포맷 적용하여 JSON 형태로 변환한다.
 * (AS-IS: fn_make_dtsToJson2_wdf, origin: report.xml)
 * @param {Object} dtsObj 헤더 기준 데이터셋
 * @param {Object} dtsReportObj 변환 대상 데이터셋
 * @param {Array} dataFormatObj 포맷 정의
 * @returns {Object} { arrayData: Array }
 * @hidden N
 * @exception
 * @example $c.print.makeDtsToJson2Wdf(dtsHdr, dtsData, fmt);
 */
scwin.makeDtsToJson2Wdf = function (dtsObj, dtsReportObj, dataFormatObj) {
    var rtnArray = new Array();
    if (dtsReportObj == null || dtsReportObj.getTotalRow() == 0) {
        rtnArray = scwin.makeDtsToJsonOut(dtsObj);
        return { arrayData: rtnArray };
    }
    var dtsObjHeaders = (dtsObj.DataHeader).split(",");
    var dtsHeaders, dtsHeaderNm, dtsHeaderType, dfObj, dfHeaderNm, dfNm, tmpObj, dtsReportValue;
    for (var j = 1; j <= dtsReportObj.getTotalRow(); j++) {
        tmpObj = new Object();
        for (var k = 0; k < dtsObjHeaders.length; k++) {
            dtsHeaders = (dtsObjHeaders[k]).split(":");
            dtsHeaderNm = dtsHeaders[0];
            dtsHeaderType = dtsHeaders[1];
            dtsReportValue = scwin.getDtsValue(dtsReportObj, j, dtsHeaderType, dtsHeaderNm);
            if (dataFormatObj != null && dataFormatObj.length > 0) {
                for (var m = 0; m < dataFormatObj.length; m++) {
                    dfObj = (dataFormatObj[m]).split(":");
                    dfHeaderNm = dfObj[0];
                    dfNm = dfObj[1];
                    if (dtsHeaderNm == dfHeaderNm) {
                        dtsReportValue = scwin.dataFormatValue(dfNm, dtsReportValue);
                        break;
                    }
                }
            }
            tmpObj[dtsHeaderNm] = dtsReportValue;
        }
        rtnArray.push(tmpObj);
    }
    return { arrayData: rtnArray };
};

/**
 * @method
 * @name makeDtsToJson3Wdf
 * @description dtsFormatObj(리포트헤더:데이터헤더:타입) 매핑으로 dtsReportObj 데이터를 포맷 적용하여 JSON 으로 변환한다.
 * (헤더 모양이 데이터셋과 리포트가 다른 경우)
 * (AS-IS: fn_make_dtsToJson3_wdf, origin: report.xml)
 * @param {Array} dtsFormatObj 매핑 정의 ["리포트헤더:데이터헤더:타입", ...]
 * @param {Object} dtsReportObj 변환 대상 데이터셋
 * @param {Array} dataFormatObj 포맷 정의
 * @returns {Object} { arrayData: Array }
 * @hidden N
 * @exception
 * @example $c.print.makeDtsToJson3Wdf(mapArr, dtsData, fmt);
 */
scwin.makeDtsToJson3Wdf = function (dtsFormatObj, dtsReportObj, dataFormatObj) {
    var rtnArray = new Array();
    var dtsHeaders, dtsRepHeaderNm, dtsDataHeaderNm, dtsDataHeaderType, dfObj, dfHeaderNm, dfNm, tmpObj, dtsReportValue;
    for (var j = 1; j <= dtsReportObj.getTotalRow(); j++) {
        tmpObj = new Object();
        for (var k = 0; k < dtsFormatObj.length; k++) {
            dtsHeaders = (dtsFormatObj[k]).split(":");
            dtsRepHeaderNm = dtsHeaders[0];     // 리포트에 쓰일 Header 명
            dtsDataHeaderNm = dtsHeaders[1];    // 데이터셋의 Header 명
            dtsDataHeaderType = dtsHeaders[2];  // 데이터셋의 Header Type
            dtsReportValue = scwin.getDtsValue(dtsReportObj, j, dtsDataHeaderType, dtsDataHeaderNm);
            if (dataFormatObj != null && dataFormatObj.length > 0) {
                for (var m = 0; m < dataFormatObj.length; m++) {
                    dfObj = (dataFormatObj[m]).split(":");
                    dfHeaderNm = dfObj[0];
                    dfNm = dfObj[1];
                    if (dtsDataHeaderNm == dfHeaderNm) {
                        dtsReportValue = scwin.dataFormatValue(dfNm, dtsReportValue);
                        break;
                    }
                }
            }
            tmpObj[dtsRepHeaderNm] = dtsReportValue;
        }
        rtnArray.push(tmpObj);
    }
    return { arrayData: rtnArray };
};

// -----------------------------------------------------------------------------
// 3. 값 추출/포맷 (origin: report.xml)
// -----------------------------------------------------------------------------

/**
 * @method
 * @name getDtsValue
 * @description 데이터셋 셀 값을 dataType 에 따라 꺼내온다. STRING 타입은 개행(\n)을 &lt;br/&gt; 로 치환한다.
 * (AS-IS: fn_getDtsValue, origin: report.xml) — $c.ut.replaceAll → $c.str.replaceAll.
 * @param {Object} dtsObj 데이터셋
 * @param {Number} nrow 행 번호
 * @param {String} dataType 데이터 타입(STRING/BIGINT/DECIMAL 등)
 * @param {String} dtsHeaderNm 컬럼명
 * @returns {String} 셀 값
 * @hidden N
 * @exception
 * @example $c.print.getDtsValue(dts, 1, "STRING(80)", "REMK");
 */
scwin.getDtsValue = function (dtsObj, nrow, dataType, dtsHeaderNm) {
    var rtnVal = dtsObj.getCellData(nrow, dtsHeaderNm);
    if (dataType.indexOf("STRING") != -1) {
        if (rtnVal.indexOf("\n") != -1) {
            rtnVal = $c.str.replaceAll(rtnVal, "\n", "<br/>");
        }
    }
    return rtnVal;
};

/**
 * @method
 * @name dataFormatValue
 * @description 값을 지정 포맷타입으로 변환한다(숫자 콤마, 소수 3자리, 각종 날짜 포맷).
 * (AS-IS: fn_dataFormatValue, origin: report.xml)
 * AS-IS 의 $c.stf.FormatNumberEx/$c.ut.FormatTofixed/$c.stf.FormatDate* 의존을
 * $c.num.formatNumber / 인라인 toFixed / 인라인 날짜포맷으로 현대화(동작 동일).
 * @param {String} dataFormatType 포맷타입 (FormatNumberEx/FormatTofixed3/FormatDateEx~FormatDateExYYMM)
 * @param {String} dataValue 원본 값
 * @returns {String} 포맷이 적용된 값
 * @hidden N
 * @exception
 * @example $c.print.dataFormatValue("FormatNumberEx", "3000"); // "3,000"
 */
scwin.dataFormatValue = function (dataFormatType, dataValue) {
    var rtnVal;
    var s = (dataValue == null) ? "" : String(dataValue);
    switch (dataFormatType) {
        case "FormatNumberEx":
            rtnVal = $c.num.formatNumber(dataValue);
            break;
        case "FormatTofixed3":
            if ($c.util.isEmpty(dataValue) == true || dataValue == "" || dataValue == "undefined") {
                dataValue = 0;
            }
            rtnVal = Number(dataValue).toFixed(3);
            break;
        case "FormatDateEx":      // YYYYMMDD → YYYY-MM-DD
            rtnVal = (s == "") ? "" : s.substring(0, 4) + "-" + s.substring(4, 6) + "-" + s.substring(6, 8);
            break;
        case "FormatDateEx2":     // YYYYMMDD → YYYY.MM.DD
            rtnVal = (s == "") ? "" : s.substring(0, 4) + "." + s.substring(4, 6) + "." + s.substring(6, 8);
            break;
        case "FormatDateEx3":     // YYYYMMDD → YYYY년 MM월 DD일
            rtnVal = (s == "") ? "" : s.substring(0, 4) + "년 " + s.substring(4, 6) + "월 " + s.substring(6, 8) + "일";
            break;
        case "FormatDateEngEx1":  // YYYYMMDD → YYYY. MM. DD
            rtnVal = (s == "") ? "" : s.substring(0, 4) + ". " + s.substring(4, 6) + ". " + s.substring(6, 8);
            break;
        case "FormatDateEngEx2":  // YYYYMMDD → DD. MM. YYYY
            rtnVal = (s == "") ? "" : s.substring(6, 8) + ". " + s.substring(4, 6) + ". " + s.substring(0, 4);
            break;
        case "FormatDateEngEx3":  // MMDDYYYY → MM. DD. YYYY
            rtnVal = (s == "") ? "" : s.substring(0, 2) + ". " + s.substring(2, 4) + ". " + s.substring(4, 8);
            break;
        case "FormatDateExYYMM":  // YYYYMM → YYYY-MM
            rtnVal = (s == "") ? "" : s.substring(0, 4) + "-" + s.substring(4, 6);
            break;
        case "":
            break;
    }
    return rtnVal;
};
